// diet_week_data.dart
// Curated 7-day meal plans (4 distinct weekly options each) using everyday, simple, familiar foods.
// Dynamically calibrated to the client's body weight (kg) for precise caloric, macro, and portion sizing.

import 'package:flutter/material.dart';
import '../models/diet_week_models.dart';
import '../models/health_models.dart';

class DietWeekData {
  static List<DietWeekOption> getWeeklyOptions(DietPlan plan, {double weightKg = 70.0}) {
    // Normalise weight to healthy adult bounds (40kg to 160kg)
    final clampedWeight = weightKg.clamp(40.0, 160.0);
    final scale = clampedWeight / 70.0;

    switch (plan.id) {
      case 'para_sci_anti_inflammatory':
        return _buildOptionsParaSciAntiInflammatory(clampedWeight, scale);
      case 'para_pressure_ulcer_healing':
        return _buildOptionsParaPressureUlcerHealing(clampedWeight, scale);
      case 'para_bowel_bladder_management':
        return _buildOptionsParaBowelBladderManagement(clampedWeight, scale);
      case 'para_bed_bound_muscle_preservation':
        return _buildOptionsParaBedBoundMusclePreservation(clampedWeight, scale);
      case 'health_cardiac_dash':
        return _buildOptionsHealthCardiacDash(clampedWeight, scale);
      case 'health_diabetes_glycemic':
        return _buildOptionsHealthDiabetesGlycemic(clampedWeight, scale);
      case 'health_arthritis_anti_inflam':
        return _buildOptionsHealthArthritisAntiInflam(clampedWeight, scale);
      case 'health_osteoporosis_bone':
        return _buildOptionsHealthOsteoporosisBone(clampedWeight, scale);
      case 'fat_loss':
        return _buildOptionsFatLoss(clampedWeight, scale);
      case 'muscle_gain':
        return _buildOptionsMuscleGain(clampedWeight, scale);
      case 'balanced':
        return _buildOptionsBalanced(clampedWeight, scale);
      case 'keto':
        return _buildOptionsKeto(clampedWeight, scale);
      default:
        return _buildDefaultOptions(plan, clampedWeight, scale);
    }
  }

  // Helper to format portions based on body weight
  static String _portionFor(String mealType, double weightKg, {String extra = ''}) {
    final s = weightKg / 70.0;
    if (mealType == 'Breakfast') {
      final eggs = (2 * s).round().clamp(1, 4);
      final toasts = (2 * s).round().clamp(1, 3);
      if (extra.contains('Oats')) {
        final grams = (45 * s).round();
        return '${grams}g Oats cooked in ${(200 * s).round()}ml Milk';
      }
      return '$eggs Boiled/Scrambled Eggs + $toasts Toasts';
    } else if (mealType == 'Lunch') {
      final rotis = (2 * s).round().clamp(1, 4);
      final riceG = (150 * s).round();
      final proteinG = (120 * s).round();
      return '$rotis Chapatis (or ${riceG}g Rice) + ${proteinG}g Dal/Chicken';
    } else if (mealType == 'Snack') {
      final nuts = (12 * s).round().clamp(8, 25);
      return '1 Fruit + $nuts Almonds/Peanuts';
    } else {
      final rotis = (2 * s).round().clamp(1, 4);
      final proteinG = (110 * s).round();
      return '$rotis Chapatis or Khichdi + ${proteinG}g Paneer/Fish/Chicken';
    }
  }

