  static List<DietWeekOption> _buildDefaultOptions(DietPlan plan, double weightKg, double scale) {
    const days = [
      ('Monday', 'Mon'), ('Tuesday', 'Tue'), ('Wednesday', 'Wed'),
      ('Thursday', 'Thu'), ('Friday', 'Fri'), ('Saturday', 'Sat'), ('Sunday', 'Sun')
    ];
    final cals = (plan.dailyCaloriesTarget * scale).round();
    final p = plan.targetProtein * scale;
    final c = plan.targetCarbs * scale;
    final f = plan.targetFat * scale;

    return [
      DietWeekOption(
        id: '${plan.id}_opt1',
        title: 'Option 1: Balanced Home Plan',
        tag: 'Everyday Simple',
        description: 'Clean, simple home-cooked meals calibrated precisely to your ${weightKg.toStringAsFixed(1)} kg body weight.',
        accentColor: plan.accentColor,
        days: days.asMap().entries.map((e) {
          final idx = e.key;
          final d = e.value;
          return DietDayPlan(
            dayNumber: idx + 1,
            dayName: d.$1,
            dayShort: d.$2,
            dayFocus: 'Day ${idx + 1} Everyday Wholesome Balance',
            totalCalories: cals,
            totalProtein: p,
            totalCarbs: c,
            totalFat: f,
            dailyTip: 'Drink water between meals and choose simple home-cooked foods.',
            meals: [
              DietMealItem(
                type: 'Breakfast', time: '8:00 AM', name: 'Oats & Banana',
                portion: _portionFor('Breakfast', weightKg, extra: 'Oats'),
                calories: (cals * 0.25).round(), protein: p * 0.25, carbs: c * 0.25, fat: f * 0.25,
                tip: 'Start your morning with a glass of warm water.', icon: '🥣',
              ),
              DietMealItem(
                type: 'Lunch', time: '1:00 PM', name: 'Yellow Dal & Roti',
                portion: _portionFor('Lunch', weightKg),
                calories: (cals * 0.35).round(), protein: p * 0.35, carbs: c * 0.35, fat: f * 0.35,
                tip: 'Eat fresh salad first to promote digestive satiety.', icon: '🥗',
              ),
              DietMealItem(
                type: 'Snack', time: '4:30 PM', name: 'Apple & Peanuts',
                portion: _portionFor('Snack', weightKg),
                calories: (cals * 0.15).round(), protein: p * 0.15, carbs: c * 0.15, fat: f * 0.15,
                tip: 'Healthy nuts prevent late afternoon hunger spikes.', icon: '🍎',
              ),
              DietMealItem(
                type: 'Dinner', time: '8:00 PM', name: 'Dal Khichdi & Curd',
                portion: _portionFor('Dinner', weightKg),
                calories: (cals * 0.25).round(), protein: p * 0.25, carbs: c * 0.25, fat: f * 0.25,
                tip: 'Eat dinner at least 2 hours before going to bed.', icon: '🍲',
              ),
            ],
          );
        }).toList(),
      ),
    ];
  }
